import {BY_ID, LIMITS, CATALOG_VERSION, QUESTIONS, MODULES} from './catalog.js';
import {BY_ID as OLD} from './catalog-v1.js';
import * as legacy from './engine-v1.js';
export const copy=value=>structuredClone(value);
export const LEGACY='2026.09-v1';
export const catalogFor=d=>d.catalogVersion===LEGACY?OLD:BY_ID;
export function fresh(){return {schemaVersion:2,catalogVersion:CATALOG_VERSION,draft:{catalogVersion:CATALOG_VERSION,name:'',iteration:1,status:'draft',units:[],rationale:Object.fromEntries(QUESTIONS.map(([k])=>[k,'']))},submissions:[]};}
export function unitCost(u,version=CATALOG_VERSION){if(version===LEGACY)return OLD[u.type].cost;const c=BY_ID[u.type],q={...c.cost};for(const m of u.modules||[])for(const k of Object.keys(q))q[k]+=c.moduleCosts[m][k];return Object.fromEntries(Object.entries(q).map(([k,v])=>[k,v/4]));}
export function totals(units,version=CATALOG_VERSION){const q={build:0,operation:0,personnel:0};for(const u of units){const p=unitCost(u,version);for(const k of Object.keys(q))q[k]+=p[k]*4;}return Object.fromEntries(Object.entries(q).map(([k,v])=>[k,v/4]));}
export const configuration=u=>u.type+':'+[...(u.modules||[])].sort().join(',');
export function groupUnits(units){const groups=new Map();for(const u of units){const key=configuration(u);if(!groups.has(key))groups.set(key,[]);groups.get(key).push(u);}return [...groups.values()];}
export function freeHosts(units,type,excludeId){const c=BY_ID[type];return units.filter(u=>c?.hosts?.includes(u.type)&&units.filter(p=>p.id!==excludeId&&p.type===type&&p.parentId===u.id).length<(BY_ID[u.type].capacity?.[type]||1));}
export function freeSupports(units,type,excludeId){const c=BY_ID[type];return units.filter(u=>u.type===c.support&&!units.some(p=>p.id!==excludeId&&p.supportId===u.id));}
export function issues(units){const errors=[],ids=new Set(),usedSupports=new Set();for(const u of units){const c=BY_ID[u.type];if(!c){errors.push('Unbekannte Karte.');continue;}if(ids.has(u.id))errors.push('Doppelte Einheitenkennung.');ids.add(u.id);
if(c.unique&&units.filter(x=>x.type===u.type).length>1)errors.push(c.name+' ist nur einmal wählbar.');
const mods=u.modules||[];if(!Array.isArray(mods)||mods.length>(c.slots||0)||new Set(mods).size!==mods.length){errors.push('Ungültige oder zu viele Spezialisierungen.');continue;}
for(const m of mods)if(!Object.hasOwn(c.moduleCosts,m))errors.push('Diese Spezialisierung ist für '+c.name+' nicht erlaubt.');
for(const required of [...c.requires||[],...mods.flatMap(m=>Object.hasOwn(MODULES,m)?MODULES[m].requires||[]:[])])if(!units.some(x=>x.type===required))errors.push(c.name+' benötigt '+BY_ID[required].name+'.');
if(c.hosts){if(!u.parentId&&!c.optionalHost)errors.push(c.name+' benötigt eine zugeordnete Plattform.');if(u.parentId&&!freeHosts(units,u.type,u.id).some(p=>p.id===u.parentId))errors.push('Ungeeignete oder voll belegte Plattform für '+c.name+'.');}else if(u.parentId)errors.push(c.name+' kann keiner Plattform zugeordnet werden.');
if(c.support&&u.parentId){const support=units.find(x=>x.id===u.supportId);if(!support||support.type!==c.support)errors.push(c.name+' benötigt ein eigenes Paket '+BY_ID[c.support].name+'.');if(usedSupports.has(u.supportId))errors.push('Ein Logistikpaket kann nur ein Kräftepaket unterstützen.');usedSupports.add(u.supportId);}else if(u.supportId)errors.push('Unerlaubte Unterstützungszuordnung.');
}return [...new Set(errors)];}
function editable(state){if(state.draft.status!=='draft')throw new Error('Dieser Entwurf ist abgegeben. Beginnt eine Überarbeitung.');}
function checked(state){const errors=issues(state.draft.units);if(errors.length)throw new Error(errors.join(' '));return state;}
export function availability(units,type){const c=BY_ID[type];if(!c)return 'Unbekannte Karte.';if(c.unique&&units.some(u=>u.type===type))return 'Bereits in eurer Flotte.';const missing=(c.requires||[]).filter(id=>!units.some(u=>u.type===id)).map(id=>BY_ID[id].name);if(missing.length)return 'Benötigt: '+missing.join(', ');if(c.hosts&&!c.optionalHost&&!freeHosts(units,type).length)return 'Benötigt eine freie Plattform: '+c.hosts.map(id=>BY_ID[id].name).join(' oder ');return '';}
export function addUnit(state,type,options={}){editable(state);if(state.draft.units.length>=1000)throw new Error('Maximal 1.000 Bausteine pro Entwurf.');const why=availability(state.draft.units,type);if(why)throw new Error(why);const next=copy(state),c=BY_ID[type],parentId=options.parentId??(c.hosts&&!c.optionalHost?freeHosts(next.draft.units,type)[0]?.id:null);next.draft.units.push({id:options.id||crypto.randomUUID(),type,modules:[...options.modules||[]].sort(),parentId,supportId:parentId&&c.support?options.supportId||null:null});return checked(next);}
export function removeUnit(state,id){editable(state);if(!state.draft.units.some(u=>u.id===id))throw new Error('Einheit nicht gefunden.');const next=copy(state);next.draft.units=next.draft.units.filter(u=>u.id!==id);try{return checked(next);}catch(e){throw new Error('Zuerst abhängige Pakete entfernen oder umordnen. '+e.message);}}
export function setModules(state,id,modules){editable(state);const next=copy(state),u=next.draft.units.find(u=>u.id===id);if(!u)throw new Error('Einheit nicht gefunden.');u.modules=[...modules].sort();return checked(next);}
export function assignUnit(state,id,parentId,supportId){editable(state);const next=copy(state),u=next.draft.units.find(u=>u.id===id);if(!u)throw new Error('Einheit nicht gefunden.');u.parentId=parentId||null;u.supportId=u.parentId?supportId||null:null;return checked(next);}
export function submissionErrors(draft){if(draft.catalogVersion===LEGACY)return legacy.submissionErrors(draft);const errors=issues(draft.units),cost=totals(draft.units);if(!draft.name.trim())errors.push('Gebt eurer Gruppe einen Namen.');if(!draft.units.length)errors.push('Fügt mindestens einen Baustein hinzu.');for(const k of Object.keys(LIMITS))if(cost[k]>LIMITS[k])errors.push(({build:'Aufbaukapital',operation:'Jährlicher Betrieb',personnel:'Personal'})[k]+' überschritten.');for(const [k,label]of QUESTIONS)if(!draft.rationale[k]?.trim())errors.push(label);return errors;}
export function submit(state,now=new Date().toISOString()){editable(state);if(state.submissions.length>=100)throw new Error('Maximal 100 Abgaben.');const errors=submissionErrors(state.draft);if(errors.length)throw new Error(errors.join(' '));const next=copy(state);next.draft.status='submitted';next.submissions.push({...copy(next.draft),submittedAt:now});return next;}
export function migrateDraft(d){const next=copy(d),units=[];for(const u of d.units){if(u.type==='effectors')continue;const n=u.type==='helicopter'?2:u.type==='transport'?6:u.type==='patrol'?2:1;for(let i=0;i<n;i++){const type=({airdefense:'frigate',transport:'helicopter',patrol:'plane',drone:'rotorDrone'})[u.type]||u.type;units.push({...u,id:i?crypto.randomUUID():u.id,type,modules:u.type==='airdefense'?['air']:['helicopter','patrol'].includes(u.type)?['asw']:[]});}}
if(units.length>1000)throw new Error('Die Einzelauflösung überschreitet 1.000 Bausteine. Der bisherige Stand bleibt erhalten.');for(const u of d.units.filter(u=>u.type==='effectors'))units.find(x=>x.id===u.parentId).modules.push('strike');for(const u of units)u.modules.sort();next.units=units;next.catalogVersion=CATALOG_VERSION;const errors=issues(units);if(errors.length)throw new Error('Umstellung nicht möglich: '+errors.join(' '));return next;}
export function revise(state){if(state.draft.status!=='submitted')throw new Error('Gebt zunächst euren aktuellen Entwurf ab.');if(state.submissions.length>=100)throw new Error('Maximal 100 Abgaben.');const next=copy(state);if(next.draft.catalogVersion===LEGACY)next.draft=migrateDraft(next.draft);next.draft.status='draft';next.draft.iteration++;return next;}
export function parseDocument(raw){if(raw?.schemaVersion===1){const old=legacy.parseDocument(raw);return {schemaVersion:2,catalogVersion:CATALOG_VERSION,draft:old.draft.status==='draft'?migrateDraft(old.draft):{...old.draft,catalogVersion:LEGACY},submissions:old.submissions.map(d=>({...d,catalogVersion:LEGACY}))};}
if(!raw||raw.schemaVersion!==2||raw.catalogVersion!==CATALOG_VERSION)throw new Error('Diese Datei gehört nicht zur unterstützten Version des Flottenateliers.');
const clean=(d,snapshot=false)=>{if(!d||![CATALOG_VERSION,LEGACY].includes(d.catalogVersion)||typeof d.name!=='string'||d.name.length>100||!Number.isSafeInteger(d.iteration)||d.iteration<1||!['draft','submitted'].includes(d.status)||!Array.isArray(d.units)||d.units.length>1000||(d.catalogVersion===LEGACY&&d.status!=='submitted'))throw new Error('Ungültiger Entwurf in der Datei.');
const catalog=catalogFor(d),old=d.catalogVersion===LEGACY;const units=d.units.map(u=>{if(!u||!catalog[u.type]||typeof u.id!=='string'||!u.id.length||u.id.length>100||!['parentId','supportId'].every(k=>u[k]===null||typeof u[k]==='string')||(!old&&(!Array.isArray(u.modules)||u.modules.some(m=>typeof m!=='string'))))throw new Error('Ungültige Einheit in der Datei.');return {id:u.id,type:u.type,parentId:u.parentId,supportId:u.supportId,...old?{}:{modules:[...u.modules].sort()}};});const errors=(old?legacy.issues:issues)(units);if(errors.length)throw new Error(errors.join(' '));const rationale={};for(const [k]of QUESTIONS){if(typeof d.rationale?.[k]!=='string'||d.rationale[k].length>5000)throw new Error('Ungültige Begründung in der Datei.');rationale[k]=d.rationale[k];}const result={catalogVersion:d.catalogVersion,name:d.name,iteration:d.iteration,status:d.status,units,rationale};if(d.status==='submitted'&&submissionErrors(result).length)throw new Error('Ungültige Abgabe in der Datei.');if(snapshot){if(d.status!=='submitted'||typeof d.submittedAt!=='string'||!Number.isFinite(Date.parse(d.submittedAt)))throw new Error('Ungültige Abgabe in der Datei.');result.submittedAt=d.submittedAt;}return result;};
if(!Array.isArray(raw.submissions)||raw.submissions.length>100)throw new Error('Ungültige Versionsliste.');const draft=clean(raw.draft),submissions=raw.submissions.map(d=>clean(d,true));if(submissions.some((s,i)=>s.iteration!==i+1))throw new Error('Ungültige Reihenfolge der Abgaben.');if(draft.iteration!==submissions.length+(draft.status==='draft'?1:0))throw new Error('Entwurf und Abgaben passen nicht zusammen.');if(draft.status==='submitted'){const last=submissions.at(-1);if(!last||JSON.stringify(draft)!==JSON.stringify(Object.fromEntries(Object.entries(last).filter(([k])=>k!=='submittedAt'))))throw new Error('Abgegebener Entwurf wurde nachträglich verändert.');}return {schemaVersion:2,catalogVersion:CATALOG_VERSION,draft,submissions};}
